        size_t a = text.find('%', i);
        if (a == string::npos) { out.append(text, i, string::npos); break; }
        size_t b = text.find('%', a + 1);
        out.append(text, i, a - i);
        out += resolve(text.substr(a + 1, b - a - 1));
        i = b + 1;
    }
    return out;
}

