public class Main {
    static String src;
    static int p = 0;
    static HashMap<String, String> subs = new HashMap<>(), memo = new HashMap<>();

    static void skipWs() { while (p < src.length() && Character.isWhitespace(src.charAt(p))) p++; }

    // Minimal JSON string reader (the input is one object of strings).
    static String readString() {
        skipWs();
        p++; // opening quote
        StringBuilder out = new StringBuilder();
        while (src.charAt(p) != '"') {
            char c = src.charAt(p++);
            if (c != '\\') { out.append(c); continue; }
            char e = src.charAt(p++);
            switch (e) {
                case 'n': out.append('\n'); break;
                case 't': out.append('\t'); break;
                case 'r': out.append('\r'); break;
                case 'b': out.append('\b'); break;
                case 'f': out.append('\f'); break;
                case 'u': out.append((char) Integer.parseInt(src.substring(p, p + 4), 16)); p += 4; break;
                default: out.append(e); // \" \\ \/
            }
        }
        p++; // closing quote
        return out.toString();
    }

    // Expand a key once; the reference graph is acyclic, so memoizing is safe.
    static String resolve(String key) {
        String done = memo.get(key);
        if (done != null) return done;
        String value = expand(subs.get(key));
        memo.put(key, value);
        return value;
    }

    static String expand(String text) {
        StringBuilder out = new StringBuilder();
        int i = 0;
        while (i < text.length()) {
            int a = text.indexOf('%', i);
            if (a < 0) { out.append(text, i, text.length()); break; }
            int b = text.indexOf('%', a + 1);
            out.append(text, i, a);
            out.append(resolve(text.substring(a + 1, b)));
            i = b + 1;
        }
        return out.toString();
    }

