package main

import (
	"bufio"
	"encoding/json"
	"os"
	"strings"
)

var subs map[string]string
var memo = map[string]string{}

// resolve expands a key once; the reference graph is acyclic, so memoizing is safe.
func resolve(key string) string {
	if v, ok := memo[key]; ok {
		return v
	}
	v := expand(subs[key])
	memo[key] = v
	return v
}

func expand(text string) string {
	var b strings.Builder
	for {
		a := strings.IndexByte(text, '%')
		if a < 0 {
			b.WriteString(text)
			break
		}
		e := a + 1 + strings.IndexByte(text[a+1:], '%')
		b.WriteString(text[:a])
		b.WriteString(resolve(text[a+1 : e]))
		text = text[e+1:]
	}
	return b.String()
}

func main() {
	var in struct {
		Substitutions map[string]string `json:"substitutions"`
		Template      string            `json:"template"`
	}
	if err := json.NewDecoder(os.Stdin).Decode(&in); err != nil {
		panic(err)
	}
	subs = in.Substitutions
	result := expand(in.Template)
	// printable ASCII only: escape quotes and backslashes like Python's json.dumps
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	w.WriteByte('"')
	for i := 0; i < len(result); i++ {
		c := result[i]
		if c == '"' || c == '\\' {
			w.WriteByte('\\')
		}
		w.WriteByte(c)
	}
	w.WriteString("\"\n")
}
